"""Implement a Min Heap — array-backed binary heap.

Sift up after an append, sift down after moving the last element to the root.
Both walk one root-to-leaf path, hence the log n bound.

Time: O(log n) push/pop, O(1) peek   Space: O(n)
"""


class MinHeap:
    def __init__(self):
        self._data = []

    def _sift_up(self, i: int) -> None:
        while i > 0:
            parent = (i - 1) // 2
            if self._data[i] >= self._data[parent]:
                break
            self._data[i], self._data[parent] = self._data[parent], self._data[i]
            i = parent

    def _sift_down(self, i: int) -> None:
        n = len(self._data)
        while True:
            smallest = i
            for child in (2 * i + 1, 2 * i + 2):
                if child < n and self._data[child] < self._data[smallest]:
                    smallest = child
            if smallest == i:
                return
            self._data[i], self._data[smallest] = self._data[smallest], self._data[i]
            i = smallest

    def push(self, val: int) -> None:
        self._data.append(val)
        self._sift_up(len(self._data) - 1)

    def pop(self) -> int:
        if not self._data:
            return -1
        top = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return top

    def peek(self) -> int:
        return self._data[0] if self._data else -1

    def size(self) -> int:
        return len(self._data)
